// Sounds → the kit workspace, AS GRAPH SOURCE (#4215, epic #3604). Transcribed from the live feature file: the runtime
// loader compiles this and mounts it, resolving every import to the app's real modules (the shared/ui
// design system + the store via appModules, the sound domain via the sounds graph-platform, and the
// sibling views as @/components/* graph records). Behaviour runs here.
// The Sounds tab (#3072 · #3077) — the synthesis-first audio library, on the shared GraphCanvas stack
// like Components/Algorithms. The CENTER is the kit's composition graph (Primitives → Voices → Cues,
// wired by `composes`); the LEFT rail is a folder tree of cues/voices/primitives; the inspector shows the
// selected node. Clicking a graph node plays it; the rail browses quietly (Play is in the inspector).
import { useEffect, useMemo, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Eyebrow } from "@/shared/ui/typography/Eyebrow";
import { Button } from "@/shared/ui/controls/Button";
import { GraphCanvas, ZoomControls } from "@/shared/ui/layouts/GraphCanvas";
import { useGraphViewport } from "@/shared/ui/layouts/useGraphViewport";
import { useCrumbEntity } from "@/shared/hooks/useCrumbEntity";
import { usePageTabs } from "@/shared/hooks/usePageTabs";
import { useScreenDescriptor } from "@/shared/hooks/useScreenDescriptor";
import { Screen } from "@/shared/ui/layouts/Screen";
import { SoundsKitGraph } from "@/features/sounds/SoundsKitGraph";
import { SoundsRail } from "@/features/sounds/SoundsRail";
import { SoundsInspector } from "@/features/sounds/SoundsInspector";
import { buildSoundGraph, layoutSoundGraph, playableCueForNode, NODE_W, NODE_H, type SoundNode } from "@/features/sounds/lib/soundGraph";
import { playCue } from "@/features/sounds/lib/synth";
import { BUILTIN_KITS } from "@/features/sounds/lib/soundKits";
import { useSoundKits } from "@/features/sounds/useSoundKits";

export function SoundsWorkspace() {
  // Seed-first, hydrated from the durable bsc-sound store (#3080). BUILTIN_KITS[0] is the guaranteed
  // non-empty fallback for the first paint.
  const kits = useSoundKits();

  // ── THE KIT IS THE AXIS (`define-the-axis-for-teams-data-and-sounds`) ─────────────────────────
  //
  // This page hardcoded `kits[0]` with a note that multi-kit selection "lands later"; the tab bar is
  // that selection. The axis is the KIT rather than a technology because a sound kit carries no
  // technology facet at any level — `studioSessions.ts` says as much, which is why the sound-designer
  // is a single studio while the designer and librarian split per technology. Inventing a technology
  // here to match the other two graphs would be chrome asserting a distinction the store does not make.
  //
  // Single-valued today (one packaged kit, `signal`), and that is honest rather than a placeholder: the
  // bar shows what the library holds, and a second kit appears as a second tab with no code change.
  const kitTabs = useMemo(
    () => (kits.length ? kits : BUILTIN_KITS).map((k) => ({ id: k.id, label: k.name, hint: `${k.name} sound kit` })),
    [kits],
  );
  // UNCONTROLLED (`navigation-vocabulary-follows-the-new-page-structure`): the active kit is READ from
  // `activePageTab["sounds"]`, so `bsc navigate page <kitId>` reaches it and the choice survives a
  // restart. A controlled tab would keep the selection in the component, where navigate cannot reach.
  //
  // Tear-off is not wired: `studioDetached` looks for the sound-designer's `sectionId` ("sounds"), not
  // a kit id, so a detached kit tab would be a window its dock does not follow.
  const { tabs, activeId, select: selectTab, reorder } = usePageTabs("sounds", kitTabs);
  const kit = kits.find((k) => k.id === activeId) ?? kits[0] ?? BUILTIN_KITS[0];
  useCrumbEntity("sounds", kit.name);

  const graph = useMemo(() => buildSoundGraph(kit), [kit]);
  const layout = useMemo(() => layoutSoundGraph(graph), [graph]);
  const [selected, setSelected] = useState<string | null>(null);
  const selectedNode = selected ? graph.nodes.find((n) => n.id === selected) ?? null : null;

  const vp = useGraphViewport(layout.world, { contentBounds: () => layout.bounds });
  // Frame the graph once on mount (like AlgorithmsWorkspace) — we only want the initial fit.
  useEffect(() => { vp.fit(); }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const play = (node: SoundNode) => {
    const cue = playableCueForNode(node, kit);
    if (cue) playCue(cue, kit);
  };
  // Rail click: select + pan to the node, no sound (browse quietly).
  const select = (id: string) => {
    setSelected(id);
    const p = layout.pos.get(id);
    if (p) vp.centerOn(p.x + NODE_W / 2, p.y + NODE_H / 2);
  };
  // Graph-node click: select + play.
  const activate = (id: string) => {
    setSelected(id);
    const node = graph.nodes.find((n) => n.id === id);
    if (node) play(node);
  };

  const counts = useMemo(() => ({
    cues: graph.nodes.filter((n) => n.kind === "cue").length,
    voices: graph.nodes.filter((n) => n.kind === "voice").length,
    primitives: graph.nodes.filter((n) => n.kind === "primitive").length,
  }), [graph.nodes]);

  // WHAT `bsc app go` CAN SELECT HERE (`the-shared-navigation-mechanism-drill-select-and-show`): the
  // kit's nodes, through the RAIL's `select` — it pans to the node and plays nothing, which is what a
  // session looking at the graph wants.
  useScreenDescriptor({
    workspace: "sounds",
    page: activeId,
    layer: "kit",
    drill: [],
    selection: selected,
    targets: graph.nodes.map((n) => ({ id: n.id, label: n.label, drillable: false, selectable: true })),
    select: (id) => (id ? select(id) : setSelected(null)),
  });

  const toolbar = (
    <>
      <Eyebrow size={10}>Sounds</Eyebrow>
      <Text mono size="xxs" tone="dim">{kit.name} · {counts.cues} cues · {counts.voices} voices · {counts.primitives} primitives</Text>
      <Box style={{ flex: 1 }} />
      <ZoomControls vp={vp} />
      <Button size="sm" variant="ghost" onClick={vp.fit}>Fit</Button>
    </>
  );

  return (
    <Screen
      className="sounds-workspace"
      tabs={tabs}
      active={activeId}
      onSelect={selectTab}
      onReorder={reorder}
    >
    <GraphCanvas
      vp={vp}
      world={layout.world}
      grid
      toolbar={toolbar}
      rail={<SoundsRail graph={graph} selected={selected} onSelect={select} />}
      railResizable
      railWidth={230}
      inspector={<SoundsInspector node={selectedNode} kit={kit} onPlay={play} />}
      inspectorResizable
      inspectorWidth={320}
      onBackgroundClick={() => setSelected(null)}
    >
      <SoundsKitGraph graph={graph} layout={layout} selected={selected} onActivate={activate} />
    </GraphCanvas>
    </Screen>
  );
}

